# gitsim: trình mô phỏng Git đơn giản (chỉ để học, không phải Git thật) / a tiny Git simulator for learning.
import hashlib, shlex

_REMOTES = {}

class Git:
    def __init__(self):
        self.files = {}            # working directory: tên file -> nội dung
        self.commits = {}          # id -> dict(parents, tree, msg, n)
        self.branches = {}         # tên nhánh -> id commit
        self.head = None           # tên nhánh hiện tại
        self.index = {}            # vùng staging
        self.inited = False
        self.merging = None        # nhánh đang merge dở (xung đột)
        self.remotes = {}          # tên -> url
        self.tracking = {}         # "origin/main" -> id
        self.upstream = {}         # nhánh -> "origin/nhánh"
        self._n = 0
        self.config = {}

    # ---------- tiện ích ----------
    def write(self, name, text): self.files[name] = text
    def read(self, name): return self.files.get(name)
    def remove(self, name): self.files.pop(name, None)
    def _tree(self, cid): return dict(self.commits[cid]["tree"]) if cid else {}
    def _head_id(self): return self.branches.get(self.head)
    def _anc(self, cid):
        seen, st = set(), [cid]
        while st:
            c = st.pop()
            if c and c not in seen:
                seen.add(c); st.extend(self.commits[c]["parents"])
        return seen
    def _base(self, a, b):
        common = self._anc(a) & self._anc(b)
        return max(common, key=lambda c: self.commits[c]["n"]) if common else None
    def _mk(self, parents, tree, msg):
        self._n += 1
        cid = hashlib.sha1(f"{parents}{sorted(tree.items())}{msg}{self._n}".encode()).hexdigest()[:7]
        self.commits[cid] = dict(parents=parents, tree=dict(tree), msg=msg, n=self._n)
        return cid

    # ---------- chạy lệnh ----------
    def run(self, line):
        a = shlex.split(line)
        if not a or a[0] != "git": return f"{a[0] if a else ''}: command not found"
        cmd, args = (a[1] if len(a) > 1 else ""), a[2:]
        if cmd == "init":
            self.inited = True; self.head = "main"
            return "Initialized empty Git repository"
        if cmd == "clone":
            url = args[0]
            if url not in _REMOTES: return f"fatal: repository '{url}' not found"
            r = _REMOTES[url]
            self.inited = True; self.head = "main"; self.remotes["origin"] = url
            self.commits = {k: dict(v) for k, v in r["commits"].items()}
            self.branches = {"main": r["branches"].get("main")}
            self.tracking = {f"origin/{k}": v for k, v in r["branches"].items()}
            self.upstream = {"main": "origin/main"}
            self.files = self._tree(self.branches["main"]); self.index = dict(self.files)
            self._n = max([c["n"] for c in self.commits.values()] or [0])
            return f"Cloning into '{url.rsplit('/',1)[-1]}'... done."
        if cmd == "config": return self._config(args)
        if not self.inited: return "fatal: not a git repository (or any of the parent directories): .git"
        f = getattr(self, "_" + cmd.replace("-", "_"), None)
        if not f: return f"git: '{cmd}' is not supported by this simulator"
        return f(args)

    def _config(self, a):
        if a and a[0] == "--list": return "\n".join(f"{k}={v}" for k, v in sorted(self.config.items()))
        a = [x for x in a if x != "--global"]
        if len(a) == 2: self.config[a[0]] = a[1]; return ""
        return self.config.get(a[0], "") if a else ""

    def _status(self, a):
        h = self._tree(self._head_id()); out = [f"On branch {self.head}"]
        staged = {k: ("new file" if k not in h else "modified") for k in self.index if h.get(k) != self.index[k]}
        staged.update({k: "deleted" for k in h if k not in self.index})
        unst = {k: ("modified" if k in self.index else None) for k in self.files if k in self.index and self.files[k] != self.index[k]}
        unst.update({k: "deleted" for k in self.index if k not in self.files})
        untr = [k for k in self.files if k not in self.index]
        if self.merging: out.append("You have unmerged paths.")
        if staged: out += ["Changes to be committed:"] + [f"\t{v}:   {k}" for k, v in sorted(staged.items())]
        if unst: out += ["Changes not staged for commit:"] + [f"\t{v}:   {k}" for k, v in sorted(unst.items())]
        if untr: out += ["Untracked files:"] + [f"\t{k}" for k in sorted(untr)]
        if not (staged or unst or untr): out.append("nothing to commit, working tree clean")
        return "\n".join(out)

    def _add(self, a):
        for p in a:
            if p in (".", "-A"):
                self.index = dict(self.files)
            elif p in self.files: self.index[p] = self.files[p]
            elif p in self.index: del self.index[p]
            else: return f"fatal: pathspec '{p}' did not match any files"
        return ""

    def _commit(self, a):
        msg = a[a.index("-m") + 1] if "-m" in a else None
        if msg is None: return "error: commit message required (use -m)"
        h = self._head_id()
        if self.merging:
            if any("<<<<<<<" in v for v in self.index.values()): return "error: Committing is not possible because you have unmerged files."
            cid = self._mk([h, self.merging], self.index, msg); self.merging = None
        else:
            if self.index == self._tree(h): return "nothing to commit, working tree clean"
            cid = self._mk([h] if h else [], self.index, msg)
        self.branches[self.head] = cid
        return f"[{self.head} {cid}] {msg}"

    def _log(self, a):
        h = self._head_id()
        if not h: return f"fatal: your current branch '{self.head}' does not have any commits yet"
        ids = sorted(self._anc(h), key=lambda c: -self.commits[c]["n"])
        return "\n".join(f"{c} {self.commits[c]['msg']}" for c in ids)

    def _branch(self, a):
        if not a: return "\n".join(("* " if b == self.head else "  ") + b for b in sorted(self.branches))
        if not self._head_id(): return "fatal: not a valid object name: no commits yet"
        if a[0] == "-d":
            self.branches.pop(a[1], None); return f"Deleted branch {a[1]}"
        if a[0] in self.branches: return f"fatal: a branch named '{a[0]}' already exists"
        self.branches[a[0]] = self._head_id(); return ""

    def _switch(self, a):
        create = "-c" in a or "-b" in a
        name = [x for x in a if not x.startswith("-")][0]
        if create:
            if name in self.branches: return f"fatal: a branch named '{name}' already exists"
            self.branches[name] = self._head_id(); self.head = name
            return f"Switched to a new branch '{name}'"
        if name not in self.branches: return f"fatal: invalid reference: {name}"
        if self.files != self.index or self.index != self._tree(self._head_id()):
            if self._tree(self.branches[name]) != self._tree(self._head_id()):
                return "error: Your local changes would be overwritten by checkout. Commit or stash them first."
        self.head = name; t = self._tree(self.branches[name]); self.files = dict(t); self.index = dict(t)
        return f"Switched to branch '{name}'"
    _checkout = _switch

    def _merge(self, a):
        o = a[0]
        if o not in self.branches: return f"merge: {o} - not something we can merge"
        ours, theirs = self._head_id(), self.branches[o]
        if theirs in self._anc(ours): return "Already up to date."
        if ours in self._anc(theirs):
            self.branches[self.head] = theirs; t = self._tree(theirs); self.files, self.index = dict(t), dict(t)
            return f"Updating {ours}..{theirs}\nFast-forward"
        return self._three(ours, theirs, o)

    def _three(self, ours, theirs, label):
        b = self._tree(self._base(ours, theirs)); O, T = self._tree(ours), self._tree(theirs)
        res, bad = {}, []
        for k in sorted(set(b) | set(O) | set(T)):
            bo, oo, to = b.get(k), O.get(k), T.get(k)
            if oo == to: v = oo
            elif oo == bo: v = to
            elif to == bo: v = oo
            else:
                v = f"<<<<<<< HEAD\n{(oo or '').rstrip(chr(10))}\n=======\n{(to or '').rstrip(chr(10))}\n>>>>>>> {label}"; bad.append(k)
            if v is not None: res[k] = v
        self.files = dict(res)
        if bad:
            self.index = {k: v for k, v in res.items() if k not in bad}; self.merging = theirs
            for k in bad: self.index[k] = res[k]
            return "\n".join(f"CONFLICT (content): Merge conflict in {k}" for k in bad) + "\nAutomatic merge failed; fix conflicts and then commit the result."
        self.index = dict(res); cid = self._mk([ours, theirs], res, f"Merge branch '{label}'"); self.branches[self.head] = cid
        return f"Merge made by the 'ort' strategy. [{cid}]"

    def _restore(self, a):
        for p in [x for x in a if not x.startswith("-")]:
            if "--staged" in a: 
                h = self._tree(self._head_id())
                if p in h: self.index[p] = h[p]
                else: self.index.pop(p, None)
            elif p in self.index: self.files[p] = self.index[p]
        return ""

    def _revert(self, a):
        h = self._head_id(); par = self.commits[h]["parents"]
        t = self._tree(par[0] if par else None); msg = f"Revert \"{self.commits[h]['msg']}\""
        cid = self._mk([h], t, msg); self.branches[self.head] = cid; self.files, self.index = dict(t), dict(t)
        return f"[{self.head} {cid}] {msg}"

    def _remote(self, a):
        if a and a[0] == "add": self.remotes[a[1]] = a[2]; _REMOTES.setdefault(a[2], dict(commits={}, branches={})); return ""
        if a and a[0] == "-v": return "\n".join(f"{k}\t{v} (fetch)\n{k}\t{v} (push)" for k, v in self.remotes.items())
        return "\n".join(self.remotes)

    def _push(self, a):
        u = [x for x in a if x != "-u"]
        name, br = (u + [None, None])[:2]; name = name or "origin"; br = br or self.head
        if name not in self.remotes: return f"fatal: '{name}' does not appear to be a git repository"
        r = _REMOTES[self.remotes[name]]; mine = self.branches[br]
        if br in r["branches"] and r["branches"][br] not in self._anc(mine):
            return "! [rejected] %s -> %s (non-fast-forward)\nhint: Updates were rejected. Pull first (git pull) then push again." % (br, br)
        for c in self._anc(mine): r["commits"][c] = dict(self.commits[c])
        r["branches"][br] = mine; self.tracking[f"{name}/{br}"] = mine
        if "-u" in a: self.upstream[br] = f"{name}/{br}"
        return f"To {self.remotes[name]}\n * {br} -> {br}"

    def _fetch(self, a):
        name = a[0] if a else "origin"; r = _REMOTES[self.remotes[name]]
        for c, v in r["commits"].items(): self.commits.setdefault(c, dict(v))
        for b, c in r["branches"].items(): self.tracking[f"{name}/{b}"] = c
        self._n = max(self._n, max([c["n"] for c in self.commits.values()] or [0]))
        return f"From {self.remotes[name]}"

    def _pull(self, a):
        self._fetch(a[:1]); up = self.upstream.get(self.head, f"origin/{self.head}")
        if up not in self.tracking: return "Already up to date."
        o = up.split("/")[1]; self.branches["__t"] = self.tracking[up]
        try: out = self._merge(["__t"]).replace("'__t'", f"'{up}'")
        finally: self.branches.pop("__t", None)
        return out

class Shell:
    """Mô phỏng vài lệnh terminal: pwd, ls, cd, mkdir, touch, echo > file, cat."""
    def __init__(self):
        self.fs = {"home": {"you": {}}}; self.cwd = ["home", "you"]
    def _dir(self, path=None):
        d = self.fs
        for p in (path if path is not None else self.cwd): d = d[p]
        return d
    def _resolve(self, p):
        parts = [] if p.startswith("/") else list(self.cwd)
        for x in p.split("/"):
            if x in ("", "."): continue
            if x == "..": parts = parts[:-1]
            else: parts.append(x)
        return parts
    def run(self, line):
        if ">" in line:
            left, name = [x.strip() for x in line.split(">", 1)]
            txt = left[len("echo"):].strip().strip("\"'")
            self._dir()[name] = txt; return ""
        a = shlex.split(line); c = a[0]; args = a[1:]
        if c == "pwd": return "/" + "/".join(self.cwd)
        if c == "ls": return "  ".join(sorted(self._dir(self._resolve(args[0]) if args else None)))
        if c == "mkdir":
            for p in args:
                parts = self._resolve(p); self._dir(parts[:-1])[parts[-1]] = {}
            return ""
        if c == "touch":
            for p in args:
                parts = self._resolve(p); self._dir(parts[:-1]).setdefault(parts[-1], "")
            return ""
        if c == "cd":
            parts = self._resolve(args[0]) if args else ["home", "you"]
            try:
                if not isinstance(self._dir(parts), dict): return f"cd: not a directory: {args[0]}"
            except KeyError: return f"cd: no such file or directory: {args[0]}"
            self.cwd = parts; return ""
        if c == "cat":
            parts = self._resolve(args[0])
            try: return self._dir(parts[:-1])[parts[-1]]
            except KeyError: return f"cat: {args[0]}: No such file or directory"
        return f"{c}: command not found"

def show(g, line):
    print("$", line)
    out = g.run(line)
    if out: print(out)

import re

PATTERN = r"^(feat|fix|docs|style|refactor|test|chore)(\([a-z0-9-]+\))?: .{1,50}$"

def valid(msg):
    return re.match(PATTERN, msg) is not None

for m in ["feat(login): them nut dang nhap", "fix: sua loi chinh ta", "Update stuff", "feat:khong cach"]:
    print(valid(m), "-", m)

