def bump(version, level):
    a, b, c = [int(x) for x in version.split('.')]
    if level == 'major':
        return f'{a + 1}.0.0'
    if level == 'minor':
        return f'{a}.{b + 1}.0'
    return f'{a}.{b}.{c + 1}'

for lv in ('minor', 'major', 'patch'):
    print(bump('1.4.2', lv))
